import {sources,locations,items,episode,journalLessons,initialState,unlocked,choose,enter} from './story-data.js';
import {AdventureAudio} from './audio.js';
const $=s=>document.querySelector(s), music=new AdventureAudio(),KEY='choicewright:first-key:v1';
let state=initialState(),saved=null,storageOK=true,travelTimer=null,lastFocus=null,reading=false,toastTimer;
try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw?.version===1&&Array.isArray(raw.done)&&raw.vars&&episode.nodes[raw.node]){state={...initialState(),...raw};saved=raw;}}catch{}
const story=$('#story'),utility=$('#utility'),welcome=$('#welcome');
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;$('#save-note').textContent='Progress is not saved in this browser';}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function money(n){return (n<0?'−':'')+'$'+Math.abs(n).toLocaleString('en-US');}
function vars(){const v=state.vars,margin=6000-2100-500-v.housing;return {...v,reserve:money(v.reserve),margin:money(margin),afterRepair:money(v.reserve-3000),homeName:v.home==='willow'?'Willow Cottage':'Lantern House',reserveResult:v.reserve<3000?'The pouch cannot cover this repair. You would need a different, workable plan before proceeding.':v.reserve===3000?'The repair would use the entire pouch. Another surprise would have no cushion waiting for it.':'There is money left, but it is a thinner cushion than before. Consider whether that remaining amount is enough for your circumstances.',endingText:v.nextStep==='conversation'?'Your next quest: bring clear questions to an agent or lender conversation. Ask for explanations you can repeat in your own words.':v.nextStep==='prepare'?'Your next quest: give preparation a place on your calendar. Waiting with a plan is movement, too.':'Your next quest: map your actual spending, savings, and credit information. Start with understanding your situation.'};}
function interpolate(t){const v=vars();return t.replace(/\{\{(\w+)\}\}/g,(_,k)=>esc(v[k]??''));}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function openDialog(d){lastFocus=document.activeElement;if(!d.open)d.showModal();}
function stopNarration(){window.speechSynthesis?.cancel();reading=false;$('#narrate').setAttribute('aria-pressed','false');$('#narrate').textContent='◖ Read aloud';music.duck(false);}
function closeStory(){stopNarration();story.close();$('#world').focus();}
function update(){const n=state.done.length;$('#progress').style.width=n/6*100+'%';$('#progress-label').textContent=`YOUR JOURNEY · ${n} OF 6`;$('#quest-intro').textContent=state.ended?'You found your first key. Your field journal is ready for the next step.':'Visit the marked places. Gather understanding. Choose the path that fits your life.';
 $('#pins').innerHTML=locations.map((l,i)=>{const available=unlocked(state,l),done=state.done.includes(l.id);return `<button class="pin ${done?'done':!available?'locked':'active'}" style="left:${l.x}%;top:${l.y}%" data-place="${l.id}" aria-label="${esc(l.name)}${done?', completed':available?', visit':', locked'}"><span class="pin-icon">${done?'✓':available?l.symbol:'·'}</span><span class="pin-label">${esc(l.name)}</span></button>`;}).join('');
 $('#quest-list').innerHTML=locations.map((l,i)=>`<li class="${state.done.includes(l.id)?'finished':unlocked(state,l)?'current':''}"><b>${state.done.includes(l.id)?'✓':String(i+1).padStart(2,'0')}</b><button data-place="${l.id}">${l.quest}</button></li>`).join('');
 document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>travel(b.dataset.place));$('#items').innerHTML=items.map(i=>`<button class="item ${state.inventory.includes(i.id)?'earned':''}" data-item="${i.id}" title="${state.inventory.includes(i.id)?i.title:'Not found yet'}" aria-label="${state.inventory.includes(i.id)?i.title:'Unfound item'}">${state.inventory.includes(i.id)?i.symbol:'·'}</button>`).join('');document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{const i=items.find(i=>i.id===b.dataset.item);toast(state.inventory.includes(i.id)?i.title+': '+i.text:'Explore Hearthvale to discover what belongs here.');});position();$('#map-hint').textContent=state.ended?'Your first key is earned. Open your field journal.':`Next: ${locations.find(l=>!state.done.includes(l.id)&&unlocked(state,l))?.name||'explore the town'}`;}
function position(){$('#traveler').style.left=state.player.x+'%';$('#traveler').style.top=state.player.y+'%';}
function travel(id){if(!state.started)return;const loc=locations.find(l=>l.id===id);if(!unlocked(state,loc)){toast('First: '+loc.requires.filter(r=>!state.done.includes(r)).map(r=>locations.find(l=>l.id===r).name).join(' and '));return;}clearTimeout(travelTimer);state.player={x:loc.x+3,y:loc.y+7};position();music.effect();$('#map-hint').textContent='Walking to '+loc.name+'…';travelTimer=setTimeout(()=>{state.location=id;state.history=[];renderNode(loc.start);},450);}
function widget(type){if(type==='compare')return `<div class="numbers"><div><small>WILLOW · FICTIONAL / MONTH</small><strong>$2,400</strong><p class="small">Loan P&amp;I $1,600<br>Taxes &amp; insurance $400<br>Utilities $200 · Upkeep $200<br>HOA &amp; mortgage insurance $0 assumed</p></div><div><small>LANTERN · FICTIONAL / MONTH</small><strong>$3,300</strong><p class="small">Loan P&amp;I $2,200<br>Taxes &amp; insurance $600<br>Utilities $250 · Upkeep $250<br>HOA &amp; mortgage insurance $0 assumed</p></div></div>`;
 if(type==='monthly')return `<div class="numbers"><div><small>CHOSEN HOUSING BUDGET</small><strong>${money(state.vars.housing)}/mo</strong></div><div><small>AFTER EXPENSES &amp; SAVINGS GOAL</small><strong>${money(3400-state.vars.housing)}/mo</strong></div></div>`;
 if(type==='reserve')return `<div class="budget-control"><label for="reserve-range">Keep in my emergency pouch</label><input type="range" id="reserve-range" min="0" max="4000" step="500" value="${state.vars.reserve}"><output id="reserve-output" for="reserve-range">${money(state.vars.reserve)} reserved · ${money(4000-state.vars.reserve)} for furniture</output></div>`;
 if(type==='report')return `<div class="numbers"><div><small>TRAINING REPORT · OAK ACCOUNT</small><strong>30 days late</strong><p class="small">July payment reported late.</p></div><div><small>YOUR FICTIONAL BANK RECEIPT</small><strong>Paid on time</strong><p class="small">Receipt shows payment received before the due date.</p></div></div>`;
 if(type==='repair')return `<div class="numbers"><div><small>YOUR EMERGENCY POUCH</small><strong>${money(state.vars.reserve)}</strong></div><div><small>FICTIONAL REPAIR ESTIMATE</small><strong>$3,000</strong></div></div>`;return '';}
function renderNode(id){stopNarration();const node=episode.nodes[id];if(!node)return;const oldItems=state.inventory.length;state.node=id;enter(state,node);if(state.inventory.length>oldItems)music.effect(node.ending?'finish':'reward');music.mood=['inspection','self-fund','shortcut'].includes(id)?'tense':'explore';save();update();const loc=locations.find(l=>l.id===state.location);$('#scene-location').textContent=`${loc.name} · ${node.ending?'JOURNEY COMPLETE':'THE FIRST KEY'}`;
 $('#story-body').innerHTML=`<div class="scene-enter">${node.ending?'<div class="ending-seal">⚿</div>':''}<div class="character"><span class="sigil">${node.symbol}</span>${node.speaker}</div><h2>${node.title}</h2><div class="prose">${node.text.map(p=>`<p>${interpolate(p)}</p>`).join('')}</div>${node.widget?widget(node.widget):''}${node.lesson?`<div class="lesson"><small>PACK THIS FOR REAL LIFE</small>${node.lesson}</div>`:''}${node.ending?`<div class="complete-metrics"><span>6 places explored</span><span>4 discoveries earned</span><span>1 clearer next step</span></div>`:''}<div class="choices">${node.choices.map((c,i)=>`<button class="choice" data-choice="${i}"><span>${i+1}</span><div><strong>${c.label}</strong>${c.detail?`<small>${c.detail}</small>`:''}</div><span>→</span></button>`).join('')}</div></div>`;
 $('#story-body').scrollTop=0;$('#back-scene').disabled=!state.history.length;$('#scene-count').textContent=`${state.done.length}/6 places complete`;$('#scene-source').hidden=!node.source;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>act(Number(b.dataset.choice)));const range=$('#reserve-range');if(range)range.oninput=()=>{$('#reserve-output').textContent=`${money(+range.value)} reserved · ${money(4000-range.value)} for furniture`;};openDialog(story);}
function act(i){const node=episode.nodes[state.node],c=node.choices[i];if(!c)return;state.history.push(JSON.stringify({...state,history:[]}));if(state.history.length>30)state.history.shift();if(node.widget==='reserve')state.vars.reserve=+$('#reserve-range').value;music.effect();if(c.to.startsWith('@')){save();closeStory();update();if(c.to==='@journal')showJournal();if(c.to==='@series')showSeries();return;}choose(state,c);renderNode(c.to);}
$('#back-scene').onclick=()=>{if(!state.history.length)return;const history=[...state.history],previous=JSON.parse(history.pop());state={...previous,history};renderNode(state.node);};$('#close-story').onclick=closeStory;story.addEventListener('cancel',stopNarration);
$('#narrate').onclick=()=>{if(reading){stopNarration();return;}if(!window.speechSynthesis){toast('Read-aloud is not available in this browser. All dialogue is on screen.');return;}const node=episode.nodes[state.node],u=new SpeechSynthesisUtterance([node.title,...node.text.map(interpolate),node.lesson||''].join('. '));u.rate=.96;u.pitch=.93;u.lang='en-US';u.onend=u.onerror=()=>stopNarration();reading=true;$('#narrate').setAttribute('aria-pressed','true');$('#narrate').textContent='■ Stop reading';music.duck(true);speechSynthesis.speak(u);};
async function toggleMusic(){if(music.on)music.stop();else{const ok=await music.start();if(!ok)toast('Audio is unavailable here. You can keep playing quietly.');}$('#music').setAttribute('aria-pressed',String(music.on));$('#music span').textContent=music.on?'Sound on':'Sound off';}
$('#music').onclick=toggleMusic;
function utilityView(label,html){$('#utility-label').textContent=label;$('#utility-body').innerHTML=html;openDialog(utility);$('#utility-body').scrollTop=0;}
$('#close-utility').onclick=()=>{utility.close();lastFocus?.focus?.();};
function showSources(only){const entries=only?[[only,sources[only]]]:Object.entries(sources);utilityView('THE FACTS BEHIND THE ADVENTURE',`<h2>Fantasy world. Grounded lessons.</h2><p>Characters, prices, households, and outcomes are fictional. Educational claims are linked to these U.S. consumer resources. Reviewed September 5, 2026. This is introductory education, not a loan offer, credit-score forecast, or individual financial advice.</p>${entries.map(([id,s])=>`<div class="source-card"><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a><small>${s.publisher} · ${s.note}</small></div>`).join('')}<p class="small">Your gameplay stays in this browser. There is no credit pull, report upload, or application. Read-aloud uses your browser’s voice service when available.</p>`);}
$('#sources').onclick=()=>showSources();$('#scene-source').onclick=()=>showSources(episode.nodes[state.node].source);
const nextSteps=()=>state.vars.nextStep==='conversation'?['Ask an agent to explain their services, agreement, compensation, and your obligations.','Ask lenders for comparable options and explanations of all costs.','Bring questions about inspection, repairs, contract deadlines, and closing.']:state.vars.nextStep==='prepare'?['Review your actual spending and set a savings goal that fits your circumstances.','Review your credit reports; document any specific errors you identify.','Choose a date to revisit your plan with a qualified professional.']:['List the full recurring costs of owning a home, alongside your other expenses.','Separate moving costs, cash for closing, and emergency savings.','Review your credit reports and investigate information that does not match your records.'];
function journalText(){return ['THE FIRST KEY — MY FIELD JOURNAL','A Choicewright adventure · Peasant Publishing','Fictional training choices, not a loan approval or credit assessment.','',...state.done.map(id=>locations.find(l=>l.id===id).quest.toUpperCase()+'\n'+journalLessons[id]),'',`My story priority: ${state.vars.priority}`,`Fictional monthly housing budget: ${money(state.vars.housing)}`,`Fictional reserve before repair: ${money(state.vars.reserve)}`,`Repair response: ${state.vars.resolution||'Not reached yet'}`,'','MY NEXT STEPS',...nextSteps().map((s,i)=>`${i+1}. ${s}`),'','QUESTIONS FOR MY GUIDE','What does my complete monthly housing budget look like?','Which loan features and costs are different between these options?','What happens if an inspection uncovers a repair?','What should I understand or prepare before moving forward?','','SOURCES · Reviewed September 5, 2026',...Object.values(sources).map(s=>s.publisher+' — '+s.title+'\n'+s.url)].join('\n');}
function downloadJournal(){const blob=new Blob([journalText()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='The-First-Key-Field-Journal.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your field journal is ready to take with you.');}
function showJournal(){utilityView('YOUR FIELD JOURNAL',`<h2>${state.ended?'Your next chapter starts here.':'Understanding, collected.'}</h2><p>${state.done.length?`${state.done.length} of 6 places explored. These are the lessons you have gathered.`:'Your journal is empty. Visit your cottage to begin collecting lessons.'}</p>${state.done.map(id=>`<div class="journal-entry"><h3>${locations.find(l=>l.id===id).quest}</h3><p>${journalLessons[id]}</p></div>`).join('')}${state.done.includes('market')?`<div class="numbers"><div><small>FICTIONAL HOUSING BUDGET</small><strong>${money(state.vars.housing)}/mo</strong></div><div><small>RESERVE BEFORE REPAIR</small><strong>${money(state.vars.reserve)}</strong></div></div>`:''}${state.ended?`<h3>Take one step into the real world</h3><ol>${nextSteps().map(s=>`<li>${s}</li>`).join('')}</ol><p>Bring this journal to a buyer or lender conversation. Use it to explain your questions and what you want to understand next.</p>`:''}<div class="utility-actions"><button class="primary" id="download-journal">Download my journal ↓</button><button class="secondary" id="share">Share the adventure ↗</button>${state.ended?'<button class="secondary" id="restart">Try another path</button>':''}</div><p class="small">Saved only on this device. Downloading or sharing does not send your information to an agent or lender.</p>`);$('#download-journal').onclick=downloadJournal;$('#share').onclick=share;const restart=$('#restart');if(restart)restart.onclick=()=>{utilityView('ANOTHER PATH',`<h2>Start a fresh adventure?</h2><p>This replaces the saved journey on this device. Download your current field journal first if you want to keep it.</p><div class="utility-actions"><button id="confirm-restart" class="primary">Start fresh</button><button id="cancel-restart" class="secondary">Keep my journey</button></div>`);$('#confirm-restart').onclick=()=>{state=initialState();state.started=true;save();utility.close();update();renderNode('letter');};$('#cancel-restart').onclick=showJournal;};}
$('#journal').onclick=showJournal;
async function share(){const data={title:'The First Key',text:'A little adventure about a big life decision. Explore Hearthvale and find your first key.',url:location.origin+location.pathname};try{if(navigator.share)await navigator.share(data);else if(navigator.clipboard){await navigator.clipboard.writeText(data.url);toast('Adventure link copied.');}else toast('Copy the address in your browser to share this adventure.');}catch(e){if(e.name!=='AbortError')toast('Copy the address in your browser to share this adventure.');}}
function showSeries(){utilityView('THE CHOICEWRIGHT COLLECTION',`<h2>One world of possibilities.</h2><p>Adventures that help you practice the decisions waiting in real life.</p><div class="series-card"><span class="eyebrow">THE LEGEND OF HOMEOWNERSHIP · PLAYABLE NOW</span><h3>The First Key</h3><p>Explore Hearthvale, gather your questions, and take a clearer first step toward a home.</p><button class="primary" id="return-game">${state.ended?'Return to Hearthvale':'Continue my adventure'} →</button></div><div class="series-card"><span class="eyebrow">THE CREDIT COMPASS · SERIES IN DEVELOPMENT</span><h3>A number is not your story.</h3><p>A planned adventure about understanding your reports, investigating errors, building healthy habits, and recognizing credit-repair traps.</p><ol><li><b>The Hidden Ledger:</b> read a report and understand what a score represents.</li><li><b>The False Entry:</b> gather evidence and practice an accurate dispute.</li><li><b>The Steady Path:</b> work through payment and balance decisions over time.</li><li><b>The Shortcut Seller:</b> spot promises no one can guarantee.</li></ol><p class="small">Research foundation: CFPB and FTC consumer guidance. Real credit outcomes vary; this series will not promise a point increase or instant repair.</p><button class="secondary" id="credit-facts">Explore the research ↗</button></div>`);$('#return-game').onclick=()=>utility.close();$('#credit-facts').onclick=()=>showSources('rebuild');}
$('#series').onclick=showSeries;
async function begin(sound){if(sound&&!music.on)await toggleMusic();welcome.close();state.started=true;save();update();renderNode(saved?state.node:'letter');}
$('#begin').onclick=()=>begin(true);$('#quiet').onclick=()=>begin(false);if(saved?.started){$('#begin').innerHTML='Continue your adventure <span>→</span>';$('#quiet').textContent='Continue without sound';}
welcome.addEventListener('cancel',e=>e.preventDefault());
$('#world').addEventListener('keydown',e=>{if(!state.started||story.open||utility.open||welcome.open)return;const k=e.key.toLowerCase(),dirs={arrowleft:[-2,0],a:[-2,0],arrowright:[2,0],d:[2,0],arrowup:[0,-2],w:[0,-2],arrowdown:[0,2],s:[0,2]};if(dirs[k]){e.preventDefault();state.player.x=Math.max(5,Math.min(94,state.player.x+dirs[k][0]));state.player.y=Math.max(8,Math.min(89,state.player.y+dirs[k][1]));position();save();}if(k==='e'||k==='enter'){e.preventDefault();const l=[...locations].sort((a,b)=>Math.hypot(a.x-state.player.x,a.y+7-state.player.y)-Math.hypot(b.x-state.player.x,b.y+7-state.player.y))[0];if(Math.hypot(l.x-state.player.x,l.y+7-state.player.y)<17)travel(l.id);else toast('Move closer to a marked place, or select it directly.');}});
document.addEventListener('keydown',e=>{if(story.open&&!utility.open&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&['1','2','3'].includes(e.key)){e.preventDefault();act(+e.key-1);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopNarration();if(music.on)music.ctx?.suspend();}else if(music.on)music.ctx?.resume();});
setInterval(()=>{if(state.started&&!state.ended&&!document.hidden){state.elapsed+=10;save();}},10000);
window.addEventListener('pagehide',save);update();openDialog(welcome);
